function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function money($v){return number_format((float)$v,0,',',' ').' FG';}
function clean($v){return trim(preg_replace('/[|\r\n]+/',' ',(string)$v));}
function num($v){$v=str_replace([' ', "\xc2\xa0"], '', trim((string)$v));$v=str_replace(',', '.', $v);return (float)$v;}
function meta($d){$o=[];foreach(explode('|',(string)$d) as $x){$x=trim($x);if($x==='')continue;if(strpos($x,'=')!==false){[$k,$v]=explode('=',$x,2);$o[trim($k)]=trim($v);continue;}if(preg_match('/^Facture\s*:\s*(.+)$/iu',$x,$m))$o['FACTURE']=trim($m[1]);elseif(preg_match('/^Fournisseur\s*:\s*(.+)$/iu',$x,$m))$o['FOURNISSEUR']=trim($m[1]);elseif(preg_match('/^Pay[ée]\s*:\s*([0-9 .,&]+)\s*FG/iu',$x,$m))$o['PAYE']=num($m[1]);elseif(preg_match('/^Reste(?: fournisseur)?\s*:\s*([0-9 .,&]+)\s*FG/iu',$x,$m))$o['RESTE']=num($m[1]);}return $o;}
function rows($c,$ref){$a=[];$q=$c->query("SELECT m.*,p.nom,p.categorie FROM mouvements m LEFT JOIN produits p ON p.id=m.produit_id WHERE m.type='ENTREE' ORDER BY m.id ASC");while($q&&($r=$q->fetch_assoc())){$m=meta($r['description']);$rref=$m['FACTURE']??('ANCIEN-'.$r['id']);if($rref===$ref)$a[]=$r;}return $a;}
function nextId($c,$t){$q=$c->query("SELECT COALESCE(MAX(id),0)+1 n FROM `$t`");return (int)($q&&($q->fetch_assoc()['n']??1));}
function refAchat($c){$y=date('Y');$n=0;$q=$c->query("SELECT description FROM mouvements WHERE type='ENTREE' AND description LIKE 'FACTURE=ACH-$y-%'");while($q&&($r=$q->fetch_assoc()))if(preg_match('/FACTURE=ACH-'.preg_quote($y,'/').'-(\d{4})\|/',$r['description'],$m))$n=max($n,(int)$m[1]);return 'ACH-'.$y.'-'.str_pad($n+1,4,'0',STR_PAD_LEFT);}
function go($u='produits.php'){header('Location: '.$u);exit;}
function flash($t,$m){$_SESSION['f']=['t'=>$t,'m'=>$m];}
function runq($c,$s){if(!$c->query($s))throw new Exception($c->error);}

