iv class="contact">+224 611 752 767 / 622 595 362 · konatelambetenin@gmail.com · KM 36</div></div><div class="title">ACHAT<br><small><?=h($ref)?></small></div></div><div class="info"><div class="box"><b>Fournisseur</b><br><?=h($m['FOURNISSEUR']??'—')?></div><div class="box"><b>Date</b><br><?=h(date('d/m/Y',strtotime($rs[0]['date_mouvement']??'now')))?></div></div><table class="tbl"><tr><th>Article</th><th class="num">Qté</th><th class="num">Prix</th><th class="num">Montant</th></tr><?php foreach($rs as $r):?><tr><td><?=h($r['nom']??'Article')?></td><td class="num"><?=h($r['quantite'])?></td><td class="num"><?=money($r['prix'])?></td><td class="num"><?=money((float)$r['quantite']*(float)$r['prix'])?></td></tr><?php endforeach;?></table><div class="tot"><div class="row"><span>Total</span><b><?=money($tot)?></b></div><div class="row"><span>Payé</span><b><?=money($paid)?></b></div><div class="row grand"><span>Reste</span><b><?=money($rest)?></b></div></div><div class="sig"><div class="sigbox"><div class="space"><img id="si" class="hide" src="/assets/signature.png" onerror="this.style.display='none'"></div><div class="line">Responsable</div></div></div></div><script>sig.onchange=()=>si.classList.toggle('hide',!sig.checked)</script></body></html><?php exit; }

