  $old=[];$paid=0;$ref=$edit;if($edit){$old=rows($conn,$edit);if(!$old)throw new Exception('Facture introuvable.');$paid=(float)(meta($old[0]['description'])['PAYE']??0);$nt=0;foreach($ls as $l)$nt+=$l['q']*$l['p'];if($paid>$nt+.01)throw new Exception('Le nouveau total est inférieur au déjà payé.');}else $ref=refAchat($conn);
