   $nt=0;foreach($ls as $l)$nt+=$l['q']*$l['p'];$rest=max(0,$nt-$paid);foreach($ls as $l){$id=$l['id'];$q=$l['q'];$p=$l['p'];$ck=$conn->query("SELECT id FROM produits WHERE id=$id");if(!$ck||!$ck->num_rows)throw new Exception('Article introuvable.');$mid=nextId($conn,'mouvements');$d='FACTURE='.$conn->real_escape_string($ref).'|FOURNISSEUR='.$conn->real_escape_string($f).'|PAYE='.$paid.'|RESTE='.$rest.'|ACHAT';$date=date('Y-m-d H:i:s');$st=$conn->prepare("INSERT INTO mouvements(id,produit_id,type,quantite,prix,description,date_mouvement) VALUES(?,?, 'ENTREE',?,?,?,?)");$st->bind_param('iiidss',$mid,$id,$q,$p,$d,$date);if(!$st->execute())throw new Exception($st->error);$st->close();runq($conn,"UPDATE produits SET stock=stock+$q,prix_achat=$p WHERE id=$id");}$conn->commit();flash('ok','Facture enregistrée.');}catch(Throwable $e){$conn->rollback();throw $e;}go('produits.php?facture='.urlencode($ref));
 }
