 if(isset($_POST['supprimer_facture'])){$ref=clean($_POST['ref']??'');$rs=rows($conn,$ref);if(!$rs)throw new Exception('Facture introuvable.');if((float)(meta($rs[0]['description'])['PAYE']??0)>0)throw new Exception('Facture déjà payée.');$conn->begin_transaction();try{foreach($rs as $r)runq($conn,"UPDATE produits SET stock=stock-".(int)$r['quantite']." WHERE id=".(int)$r['produit_id']);foreach($rs as $rr)runq($conn,"DELETE FROM mouvements WHERE id=".(int)$rr['id']);$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}flash('ok','Facture supprimée.');go();}
